        for (int j = 0; j < 3; ++j)
            cin >> a[i][j];

    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            int toggles = a[i][j];
            if (i > 0) toggles += a[i - 1][j];
            if (i < 2) toggles += a[i + 1][j];
            if (j > 0) toggles += a[i][j - 1];
            if (j < 2) toggles += a[i][j + 1];
            cout << (toggles % 2 == 0);
        }
        cout << '\n';
    }

    return 0;
}

