using namespace std;

int main() {
    int a[5][5] = {};

    for (int i = 1; i <= 3; ++i)
        for (int j = 1; j <= 3; ++j)
            cin >> a[i][j];

    const int dx[] = {0, 0, 0, 1, -1};
    const int dy[] = {0, 1, -1, 0, 0};

    for (int i = 1; i <= 3; ++i) {
        for (int j = 1; j <= 3; ++j) {
            int presses = 0;
            for (int k = 0; k < 5; ++k)
