            cout << (1 - presses % 2);
        }
        cout << '\n';
    }

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int a[3][3];
    int lights[3][3];

    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            cin >> a[i][j];
            lights[i][j] = 1;
        }
    }

    const int dx[] = {0, 0, 0, 1, -1};
    const int dy[] = {0, 1, -1, 0, 0};

    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            if (a[i][j] % 2 == 0) continue;

            for (int k = 0; k < 5; ++k) {
                int x = i + dx[k];
                int y = j + dy[k];

                if (x >= 0 && x < 3 && y >= 0 && y < 3)
                    lights[x][y] ^= 1;
            }
        }
    }

    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j)
            cout << lights[i][j];
        cout << '\n';
    }

    return 0;
}

